-- Backfill dei 98 acquisti del 1 ottobre 2026 verificati contro il backup pre-asta.
-- Neto escluso: correzione Grabara -> Neto precedente all'asta.
-- Solo provenienza; nessuna modifica a rose, crediti o password.
BEGIN;
DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM mercato_config WHERE sessioncode='5c04ce0b-0e61-4410-940e-a07d0ba1a547' AND numeromercato=1)
THEN RAISE EXCEPTION 'Sessione diversa: riesaminare il backfill'; END IF;
IF (SELECT count(*) FROM roster_acquisition WHERE rosterentryid IN (2301,2302,2303,2305,2306,2307,2308,2309,2310,2311,2312,2313,2314,2315,2316,2317,2318,2319,2320,2321,2322,2323,2324,2325,2326,2327,2328,2329,2330,2331,2332,2333,2334,2335,2336,2337,2338,2339,2340,2341,2342,2343,2344,2345,2346,2347,2348,2349,2350,2351,2352,2353,2354,2355,2356,2357,2358,2359,2360,2361,2362,2363,2364,2365,2366,2367,2368,2369,2370,2371,2372,2373,2374,2375,2376,2377,2378,2379,2380,2381,2382,2383,2384,2385,2386,2387,2388,2389,2390,2391,2392,2393,2394,2395,2396,2397,2398,2399)) <> 98
AND (SELECT count(*) FROM rosters r JOIN player_owner_history h ON h.player_id=r.player_id AND h.participant_id=r.participant_id
 WHERE r.id IN (2301,2302,2303,2305,2306,2307,2308,2309,2310,2311,2312,2313,2314,2315,2316,2317,2318,2319,2320,2321,2322,2323,2324,2325,2326,2327,2328,2329,2330,2331,2332,2333,2334,2335,2336,2337,2338,2339,2340,2341,2342,2343,2344,2345,2346,2347,2348,2349,2350,2351,2352,2353,2354,2355,2356,2357,2358,2359,2360,2361,2362,2363,2364,2365,2366,2367,2368,2369,2370,2371,2372,2373,2374,2375,2376,2377,2378,2379,2380,2381,2382,2383,2384,2385,2386,2387,2388,2389,2390,2391,2392,2393,2394,2395,2396,2397,2398,2399) AND h.firstownedat >= timestamp '2026-10-01' AND h.firstownedat < timestamp '2026-10-02') <> 98
THEN RAISE EXCEPTION 'Acquisti modificati: riesaminare il backfill'; END IF;
END $$;
INSERT INTO roster_acquisition(id,rosterentryid,player_id,participant_id,sessioncode,purchasegroupcode,acquiredat,paidamount,repairmarket)
SELECT nextval('roster_acquisition_seq'),r.id,r.player_id,r.participant_id,'5c04ce0b-0e61-4410-940e-a07d0ba1a547',
 CASE WHEN p.role='PORTIERE' THEN 'verified-20261001-door:'||r.participant_id ELSE 'verified-20261001-roster:'||r.id END,
 h.firstownedat,r.amount,true
FROM rosters r JOIN player p ON p.id=r.player_id
JOIN player_owner_history h ON h.player_id=r.player_id AND h.participant_id=r.participant_id
WHERE r.id IN (2301,2302,2303,2305,2306,2307,2308,2309,2310,2311,2312,2313,2314,2315,2316,2317,2318,2319,2320,2321,2322,2323,2324,2325,2326,2327,2328,2329,2330,2331,2332,2333,2334,2335,2336,2337,2338,2339,2340,2341,2342,2343,2344,2345,2346,2347,2348,2349,2350,2351,2352,2353,2354,2355,2356,2357,2358,2359,2360,2361,2362,2363,2364,2365,2366,2367,2368,2369,2370,2371,2372,2373,2374,2375,2376,2377,2378,2379,2380,2381,2382,2383,2384,2385,2386,2387,2388,2389,2390,2391,2392,2393,2394,2395,2396,2397,2398,2399)
AND NOT EXISTS(SELECT 1 FROM roster_acquisition a WHERE a.rosterentryid=r.id);
COMMIT;
